5	/**
6	 * 业务异常：携带可区分的 HTTP 状态码与错误码。
7	 * 400 参数非法，404 资源不存在，409 权限/状态/幂等冲突，422 非法状态流转。
8	 */
9	public class ApiException extends RuntimeException {
10	
11	    private final HttpStatus status;
12	    private final String code;
13	    private final transient Object details;
14	
15	    private ApiException(HttpStatus status, String code, String message, Object details) {
16	        super(message);
17	        this.status = status;
18	        this.code = code;
19	        this.details = details;
20	    }
21	
22	    public HttpStatus status() {
23	        return status;
24	    }
25	
26	    public String code() {
27	        return code;
28	    }
29	
30	    /** 结构化错误明细（如未完成任务的 groupCode/taskKey、未解除阻塞的事件键列表），无则 null。 */
31	    public Object details() {
32	        return details;
33	    }
34	
35	    /** 400：请求参数缺失或非法。 */
36	    public static ApiException badRequest(String message) {
37	        return new ApiException(HttpStatus.BAD_REQUEST, "BAD_REQUEST", message, null);
38	    }
39	
40	    /** 404：事件不存在。 */
41	    public static ApiException notFound(String message) {
42	        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message, null);
43	    }
44	
45	    /** 409：权限冲突、状态冲突或幂等键冲突。 */
46	    public static ApiException conflict(String message) {
47	        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message, null);
48	    }
49	
50	    /** 409：携带结构化明细的冲突（如解决门禁未完成项、任务未解除阻塞事件列表）。 */
51	    public static ApiException conflict(String message, Object details) {
52	        return new ApiException(HttpStatus.CONFLICT, "CONFLICT", message, details);
53	    }
54	
55	    /** 422：非法状态流转。 */
56	    public static ApiException illegalTransition(String message) {
57	        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "ILLEGAL_TRANSITION", message, null);
58	    }
59	}
